import fs from "node:fs";
import path from "node:path";

import forge from "node-forge";

// Throwaway certificates for the e2e tests, generated by the global setup on
// every run so no private key is ever committed: a test CA, a server
// certificate for the fake Pomerium proxy (localhost and 127.0.0.1) and a
// client certificate, both signed by the CA, plus the client identity as a
// PKCS#12 file for the OS certificate store tests.

export const CA_NAME = { CN: "Pomerium E2E Test CA", O: "Pomerium E2E" };
export const CLIENT_NAME = { CN: "e2e-client", O: "Pomerium E2E" };
export const P12_PASSWORD = "e2e-password";

const certDir = path.resolve(__dirname, "..", "test-results", "e2e-certs");

export const certPaths = () => ({
  dir: certDir,
  ca: path.join(certDir, "ca.pem"),
  serverCert: path.join(certDir, "server.pem"),
  serverKey: path.join(certDir, "server-key.pem"),
  clientCert: path.join(certDir, "client.pem"),
  clientKey: path.join(certDir, "client-key.pem"),
  clientP12: path.join(certDir, "client.p12"),
});

const subject = (name: { CN: string; O: string }) => [
  { shortName: "CN", value: name.CN },
  { shortName: "O", value: name.O },
];

const keyToPkcs8Pem = (key: forge.pki.rsa.PrivateKey) =>
  forge.pki.privateKeyInfoToPem(forge.pki.wrapRsaPrivateKey(forge.pki.privateKeyToAsn1(key)));

let serial = 1;

const issue = (
  name: { CN: string; O: string },
  issuer: { cert: forge.pki.Certificate | null; key: forge.pki.rsa.PrivateKey | null },
  extensions: object[],
) => {
  const keys = forge.pki.rsa.generateKeyPair(2048);
  const cert = forge.pki.createCertificate();
  cert.publicKey = keys.publicKey;
  cert.serialNumber = (serial++).toString(16).padStart(2, "0");
  cert.validity.notBefore = new Date(Date.now() - 24 * 60 * 60 * 1000);
  cert.validity.notAfter = new Date(Date.now() + 365 * 24 * 60 * 60 * 1000);
  cert.setSubject(subject(name));
  cert.setIssuer(issuer.cert ? issuer.cert.subject.attributes : subject(name));
  cert.setExtensions([{ name: "subjectKeyIdentifier" }, ...extensions]);
  cert.sign(issuer.key ?? keys.privateKey, forge.md.sha256.create());
  return { cert, key: keys.privateKey };
};

/** Writes a fresh set of test certificates to certPaths(). */
export const generateCerts = () => {
  const paths = certPaths();
  fs.mkdirSync(paths.dir, { recursive: true });

  const ca = issue(CA_NAME, { cert: null, key: null }, [
    { name: "basicConstraints", cA: true, critical: true },
    { name: "keyUsage", keyCertSign: true, cRLSign: true, critical: true },
  ]);
  const server = issue({ CN: "localhost", O: "Pomerium E2E" }, ca, [
    { name: "basicConstraints", cA: false },
    { name: "keyUsage", digitalSignature: true, keyEncipherment: true, critical: true },
    { name: "extKeyUsage", serverAuth: true },
    {
      name: "subjectAltName",
      altNames: [
        { type: 2, value: "localhost" },
        { type: 7, ip: "127.0.0.1" },
      ],
    },
  ]);
  const client = issue(CLIENT_NAME, ca, [
    { name: "basicConstraints", cA: false },
    { name: "keyUsage", digitalSignature: true, keyEncipherment: true, critical: true },
    { name: "extKeyUsage", clientAuth: true },
  ]);

  const pem = forge.pki.certificateToPem;
  fs.writeFileSync(paths.ca, pem(ca.cert));
  fs.writeFileSync(paths.serverCert, pem(server.cert));
  fs.writeFileSync(paths.serverKey, keyToPkcs8Pem(server.key));
  fs.writeFileSync(paths.clientCert, pem(client.cert));
  fs.writeFileSync(paths.clientKey, keyToPkcs8Pem(client.key));
  // Triple DES, which both macOS `security import` and Windows `certutil`
  // read. It leaves out the CA, so importing it never installs a root CA.
  const p12 = forge.pkcs12.toPkcs12Asn1(client.key, [client.cert], P12_PASSWORD, {
    algorithm: "3des",
    friendlyName: "e2e-client",
  });
  fs.writeFileSync(paths.clientP12, Buffer.from(forge.asn1.toDer(p12).getBytes(), "binary"));
};
